package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is the time source used by the limiter.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New creates a bucket allowing `rate` tokens/sec up to `capacity`.
func New(capacity int, rate float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		rate:     rate,
		tokens:   float64(capacity),
		last:     now,
		clock:    clock,
	}, nil
}

// NewReal returns a bucket using the system clock.
func NewReal(capacity int, rate float64) (*TokenBucket, error) {
	return New(capacity, rate, realClock{})
}

func (b *TokenBucket) refillLocked(now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}

// AllowN reports whether n tokens are available and consumes them if so.
func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	now := b.clock.Now()
	b.refillLocked(now)
	if float64(n) > b.tokens {
		return false
	}
	b.tokens -= float64(n)
	return true
}

// Allow reports whether one token is available.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// Remaining returns the current estimated token count.
func (b *TokenBucket) Remaining() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked(b.clock.Now())
	return b.tokens
}
